 9	/* LED Definitions for STM32F469I-DISCO (Active LOW) */
10	/* LED1: PG6, LED2: PD4, LED3: PD5, LED4: PK3 */
11	#define LED1_PIN              (6UL)
12	#define LED2_PIN              (4UL)
13	#define LED3_PIN              (5UL)
14	#define LED4_PIN              (3UL)
15	
16	/* Button Definition (Active HIGH) - WAKEUP: PA0 */
17	#define BUTTON_PIN            (0UL)
18	
19	/* Hàng đợi truyền tín hiệu sự kiện từ nút bấm PA0 sang tác vụ LED3 và LCD */
20	static QueueHandle_t xButtonQueue = NULL;
21	static QueueHandle_t xUIQueue = NULL;
