125	/* Task 1: Nháy LED1 (PG6) theo chu kỳ 1000 ms (500 ms bật, 500 ms tắt) */
126	static void vTaskLED1(void *pvParameters)
127	{
128	    (void)pvParameters;
129	    for (;;) {
130	        GPIOG->BSRR = (1UL << (LED1_PIN + 16)); /* Bật LED1 (mức thấp) */
131	        vTaskDelay(pdMS_TO_TICKS(500));
132	        GPIOG->BSRR = (1UL << LED1_PIN);        /* Tắt LED1 (mức cao) */
133	        vTaskDelay(pdMS_TO_TICKS(500));
134	    }
135	}
136	
137	/* Task 2: Nháy LED2 (PD4) theo chu kỳ 400 ms (200 ms bật, 200 ms tắt) */
138	static void vTaskLED2(void *pvParameters)
139	{
140	    (void)pvParameters;
141	    for (;;) {
142	        GPIOD->BSRR = (1UL << (LED2_PIN + 16)); /* Bật LED2 */
143	        vTaskDelay(pdMS_TO_TICKS(200));
144	        GPIOD->BSRR = (1UL << LED2_PIN);        /* Tắt LED2 */
145	        vTaskDelay(pdMS_TO_TICKS(200));
146	    }
147	}
