149	/* Tác vụ đọc nút bấm PA0 và gửi thông điệp vào Queues */
150	static void vTaskButton(void *pvParameters)
151	{
152	    (void)pvParameters;
153	    uint8_t prev_state = 0;
154	
155	    for (;;) {
156	        uint8_t state = (GPIOA->IDR & (1UL << BUTTON_PIN)) ? 1 : 0;
157	        if (state && !prev_state) {
158	            uint32_t msg = 1;
159	            if (xButtonQueue != NULL) {
160	                xQueueSend(xButtonQueue, &msg, 0);
161	            }
162	            if (xUIQueue != NULL) {
163	                xQueueSend(xUIQueue, &msg, 0);
164	            }
165	        }
166	        prev_state = state;
167	        vTaskDelay(pdMS_TO_TICKS(30)); /* Lọc rung nút bấm (debounce) */
168	    }
169	}
